from functools import update_wrapper
from inspect import getmembers

from django.urls import NoReverseMatch
from django.utils.decorators import classonlymethod
from django.views.decorators.csrf import csrf_exempt

from rest_framework import generics, mixins, views
from rest_framework.decorators import MethodMapper
from rest_framework.reverse import reverse


def _is_extra_action(attr):
    return hasattr(attr, 'mapping') and isinstance(attr.mapping, MethodMapper)


def _check_attr_name(func, name):
    assert func.__name__ == name, (
        'Expected function (`{func.__name__}`) to match its attribute name '
        '(`{name}`). If using a decorator, ensure the inner function is '
        'decorated with `functools.wraps`, or that `{func.__name__}.__name__` '
        'is otherwise set to `{name}`.').format(func=func, name=name)
    return func


class ViewSetMixin:
    """
    Mixin that overrides `.as_view()` to map HTTP methods to actions.
    """

    @classonlymethod
    def as_view(cls, actions=None, **initkwargs):
        if not actions:
            raise TypeError("The `actions` argument is required for `as_view()` on a ViewSet.")

        for key in initkwargs:
            if key in cls.http_method_names:
                raise TypeError(f"Don't use `{key}` as a keyword argument to {cls.__name__}().")

        def view(request, *args, **kwargs):
            self = cls(**initkwargs)
            self.action_map = actions
            for method, action in actions.items():
                handler = getattr(self, action)
                setattr(self, method, handler)
            self.request = request
            self.args = args
            self.kwargs = kwargs
            return self.dispatch(request, *args, **kwargs)

        update_wrapper(view, cls, updated=())
        update_wrapper(view, cls.dispatch, assigned=())
        view.cls = cls
        view.initkwargs = initkwargs
        view.actions = actions
        return csrf_exempt(view)

    def initialize_request(self, request, *args, **kwargs):
        request = super().initialize_request(request, *args, **kwargs)
        self.action = self.action_map.get(request.method.lower())
        return request

    def reverse_action(self, url_name, *args, **kwargs):
        url_name = f'{self.basename}-{url_name}'
        namespace = self.request.resolver_match.namespace if self.request and self.request.resolver_match else None
        if namespace:
            url_name = f'{namespace}:{url_name}'
        kwargs.setdefault('request', self.request)
        return reverse(url_name, *args, **kwargs)

    @classmethod
    def get_extra_actions(cls):
        return [_check_attr_name(method, name) for name, method in getmembers(cls, _is_extra_action)]


class ViewSet(ViewSetMixin, views.APIView):
    """
    Base ViewSet class without any predefined actions.
    """
    pass


class GenericViewSet(ViewSetMixin, generics.GenericAPIView):
    """
    Generic ViewSet including base behavior for `get_object` and `get_queryset`.
    """
    pass


class ReadOnlyModelViewSet(mixins.RetrieveModelMixin,
                           mixins.ListModelMixin,
                           GenericViewSet):
    """
    Provides `list` and `retrieve` actions by default.
    """
    pass


class ModelViewSet(mixins.CreateModelMixin,
                   mixins.RetrieveModelMixin,
                   mixins.UpdateModelMixin,
                   mixins.DestroyModelMixin,
                   mixins.ListModelMixin,
                   GenericViewSet):
    """
    Provides `create`, `retrieve`, `update`, `partial_update`, `destroy`, and `list` actions by default.
    """
    pass
